function(container, apiUrl, tables) {
    // 業務ロジックモジュールをインポート
    const { 
        collectSalesData, 
        classifySalesDataByProduct, 
        classifySalesDataByStore, 
        filterValidProductData, 
        collectWeatherData, 
        collectEventData, 
        collectSeasonalData, 
        analyzeCorrelationSalesWeather, 
        analyzeCorrelationSalesEvent, 
        analyzeCorrelationSalesSeason, 
        compareWithHistoricalData, 
        findAlternativeComparisonData, 
        validateComparisonPeriod 
    } = window.aivicLogic || {};

    // DOM要素を取得
    const analysisTypeSelect = container.querySelector('#analysisType');
    const startDateInput = container.querySelector('#startDate');
    const endDateInput = container.querySelector('#endDate');
    const productSelect = container.querySelector('#productSelect');
    const storeSelect = container.querySelector('#storeSelect');
    const executeAnalysisBtn = container.querySelector('#executeAnalysis');
    const compareBtn = container.querySelector('#compareAnalysis');
    const correlationResultDiv = container.querySelector('#correlationResult');
    const comparisonResultDiv = container.querySelector('#comparisonResult');
    const correlationChart = container.querySelector('#correlationChart');
    const comparisonChart = container.querySelector('#comparisonChart');

    // 分析結果を保存する変数
    let currentAnalysisResult = null;

    // 初期データ読み込み
    loadInitialData();

    async function loadInitialData() {
        try {
            // 商品データ読み込み
            const products = await window.aivicApi.list('products');
            populateSelect(productSelect, products, 'id', 'name');

            // 店舗データ読み込み
            const stores = await window.aivicApi.list('stores');
            populateSelect(storeSelect, stores, 'id', 'name');

        } catch (error) {
            window.aivicNotify.error('初期データの読み込みに失敗しました: ' + error.message);
        }
    }

    function populateSelect(selectElement, data, valueField, textField) {
        selectElement.innerHTML = '<option value="">選択してください</option>';
        data.forEach(item => {
            const option = document.createElement('option');
            option.value = item[valueField];
            option.textContent = item[textField];
            selectElement.appendChild(option);
        });
    }

    // 相関分析実行
    executeAnalysisBtn.addEventListener('click', async () => {
        try {
            const analysisType = analysisTypeSelect.value;
            const startDate = startDateInput.value;
            const endDate = endDateInput.value;
            const productId = productSelect.value;
            const storeId = storeSelect.value;

            if (!analysisType || !startDate || !endDate) {
                window.aivicNotify.error('分析種別、開始日、終了日を入力してください');
                return;
            }

            // 売上データ収集
            const salesData = await collectSalesData(startDate, endDate, productId, storeId);

            if (!salesData || salesData.length === 0) {
                window.aivicNotify.error('指定期間の売上データが見つかりません');
                return;
            }

            let correlationResult;
            let externalData;

            // 分析種別に応じて相関分析実行
            switch (analysisType) {
                case 'weather':
                    externalData = await collectWeatherData(startDate, endDate);
                    correlationResult = analyzeCorrelationSalesWeather(salesData, externalData);
                    break;
                case 'event':
                    externalData = await collectEventData(startDate, endDate);
                    correlationResult = analyzeCorrelationSalesEvent(salesData, externalData);
                    break;
                case 'seasonal':
                    externalData = await collectSeasonalData(startDate, endDate);
                    correlationResult = analyzeCorrelationSalesSeason(salesData, externalData);
                    break;
                default:
                    window.aivicNotify.error('無効な分析種別です');
                    return;
            }

            // 結果を保存
            currentAnalysisResult = {
                type: analysisType,
                salesData,
                externalData,
                correlationResult,
                period: { startDate, endDate },
                filters: { productId, storeId }
            };

            // 結果表示
            displayCorrelationResult(correlationResult);
            drawCorrelationChart(correlationResult);

            window.aivicNotify.success('相関分析が完了しました');

        } catch (error) {
            window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
        }
    });

    // 比較分析実行
    compareBtn.addEventListener('click', async () => {
        try {
            if (!currentAnalysisResult) {
                window.aivicNotify.error('先に相関分析を実行してください');
                return;
            }

            const { period, filters } = currentAnalysisResult;

            // 比較期間の妥当性チェック
            const validationResult = validateComparisonPeriod(period.startDate, period.endDate);
            if (!validationResult.isValid) {
                window.aivicNotify.error(validationResult.message);
                return;
            }

            // 過去データとの比較
            let comparisonResult = await compareWithHistoricalData(
                currentAnalysisResult.correlationResult,
                period.startDate,
                period.endDate,
                filters.productId,
                filters.storeId
            );

            // 比較データが不十分な場合は代替データを検索
            if (!comparisonResult || comparisonResult.confidence < 0.5) {
                const alternativeData = await findAlternativeComparisonData(
                    currentAnalysisResult.correlationResult,
                    filters.productId,
                    filters.storeId
                );

                if (alternativeData) {
                    comparisonResult = alternativeData;
                    window.aivicNotify.info('代替データを使用して比較分析を実行しました');
                }
            }

            if (!comparisonResult) {
                window.aivicNotify.error('比較可能なデータが見つかりません');
                return;
            }

            // 結果表示
            displayComparisonResult(comparisonResult);
            drawComparisonChart(comparisonResult);

            window.aivicNotify.success('比較分析が完了しました');

        } catch (error) {
            window.aivicNotify.error('比較分析に失敗しました: ' + error.message);
        }
    });

    function displayCorrelationResult(result) {
        if (!correlationResultDiv) return;

        const html = `
            <div class="analysis-result">
                <h4>相関分析結果</h4>
                <div class="result-summary">
                    <p><strong>相関係数:</strong> ${result.correlation?.toFixed(3) || 'N/A'}</p>
                    <p><strong>決定係数 (R²):</strong> ${result.rSquared?.toFixed(3) || 'N/A'}</p>
                    <p><strong>有意性:</strong> ${result.significance || 'N/A'}</p>
                </div>
                <div class="result-details">
                    <h5>詳細分析</h5>
                    <p>${result.interpretation || '解釈データがありません'}</p>
                </div>
            </div>
        `;
        correlationResultDiv.innerHTML = html;
    }

    function displayComparisonResult(result) {
        if (!comparisonResultDiv) return;

        const html = `
            <div class="comparison-result">
                <h4>比較分析結果</h4>
                <div class="comparison-summary">
                    <p><strong>比較期間:</strong> ${result.comparisonPeriod || 'N/A'}</p>
                    <p><strong>変化率:</strong> ${result.changeRate ? (result.changeRate * 100).toFixed(1) + '%' : 'N/A'}</p>
                    <p><strong>信頼度:</strong> ${result.confidence ? (result.confidence * 100).toFixed(1) + '%' : 'N/A'}</p>
                </div>
                <div class="comparison-details">
                    <h5>比較結果</h5>
                    <p>${result.summary || '比較データがありません'}</p>
                </div>
            </div>
        `;
        comparisonResultDiv.innerHTML = html;
    }

    function drawCorrelationChart(result) {
        if (!correlationChart || !result.chartData) return;

        // 簡易チャート描画（実際の実装では Chart.js 等を使用）
        const canvas = correlationChart.querySelector('canvas') || document.createElement('canvas');
        canvas.width = 400;
        canvas.height = 300;

        if (!correlationChart.querySelector('canvas')) {
            correlationChart.appendChild(canvas);
        }

        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // 散布図の描画
        if (result.chartData && result.chartData.length > 0) {
            ctx.fillStyle = '#007bff';
            result.chartData.forEach(point => {
                const x = (point.x / 100) * canvas.width;
                const y = canvas.height - (point.y / 100) * canvas.height;
                ctx.beginPath();
                ctx.arc(x, y, 3, 0, 2 * Math.PI);
                ctx.fill();
            });
        }
    }

    function drawComparisonChart(result) {
        if (!comparisonChart || !result.chartData) return;

        // 簡易チャート描画
        const canvas = comparisonChart.querySelector('canvas') || document.createElement('canvas');
        canvas.width = 400;
        canvas.height = 300;

        if (!comparisonChart.querySelector('canvas')) {
            comparisonChart.appendChild(canvas);
        }

        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // 比較チャートの描画
        if (result.chartData && result.chartData.length > 0) {
            ctx.strokeStyle = '#28a745';
            ctx.lineWidth = 2;
            ctx.beginPath();

            result.chartData.forEach((point, index) => {
                const x = (index / (result.chartData.length - 1)) * canvas.width;
                const y = canvas.height - (point.value / 100) * canvas.height;

                if (index === 0) {
                    ctx.moveTo(x, y);
                } else {
                    ctx.lineTo(x, y);
                }
            });

            ctx.stroke();
        }
    }
}
